"""
Fournisseur d'icônes Google Material Symbols (Outlined) pour l'application IPTV.
Couleur par défaut: #e3e3e3 (comme demandé).
"""

import sys
from pathlib import Path
from typing import Dict, Optional
from PyQt6.QtGui import QIcon, QPixmap, QPainter
from PyQt6.QtCore import Qt, QByteArray
from PyQt6.QtSvg import QSvgRenderer

# Couleur standard demandée par l'utilisateur
DEFAULT_ICON_COLOR = "#e3e3e3"

def get_assets_dir() -> Path:
    """Retourne le chemin vers le dossier assets (supporte frozen/PyInstaller)."""
    if getattr(sys, "frozen", False):
        meipass = getattr(sys, "_MEIPASS", None)
        if meipass:
            d = Path(meipass) / "assets"
            if d.exists():
                return d
        exe_dir = Path(sys.executable).parent
        d = exe_dir / "assets"
        if d.exists():
            return d
        return exe_dir / "_internal" / "assets"
    else:
        return Path(__file__).resolve().parent.parent / "assets"


def get_assets_icons_dir() -> Path:
    """Retourne le chemin vers le dossier assets/icons (supporte frozen/PyInstaller)."""
    return get_assets_dir() / "icons"


def get_app_logo_pixmap(size: int = 28) -> QPixmap:
    """Retourne le logo officiel IPTV Hub haute résolution avec coins arrondis."""
    logo_file = get_assets_dir() / "logo.png"
    if logo_file.exists():
        pm = QPixmap(str(logo_file))
        if not pm.isNull():
            return pm.scaled(size, size, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
    return get_pixmap("live_tv", color="#6366f1", size=size)


def get_app_logo_icon() -> QIcon:
    """Retourne le QIcon officiel du logo de l'application (PNG universel + ICO multi-résolution)."""
    icon = QIcon()
    assets = get_assets_dir()
    png_file = assets / "logo.png"
    ico_file = assets / "logo.ico"
    if png_file.exists():
        icon.addFile(str(png_file))
    if ico_file.exists():
        icon.addFile(str(ico_file))
    if not icon.isNull():
        return icon
    return get_icon("live_tv", color="#6366f1")


