_svg_cache: Dict[str, QByteArray] = {}


def get_svg_data(icon_name: str, color: str = DEFAULT_ICON_COLOR) -> QByteArray:
    """Retourne le contenu SVG coloré pour le nom d'icône demandé."""
    cache_key = f"{icon_name}_{color}"
    if cache_key in _svg_cache:
        return _svg_cache[cache_key]

    icons_dir = get_assets_icons_dir()
    svg_file = icons_dir / f"{icon_name}.svg"

    svg_str = ""
    if svg_file.exists():
        try:
            with open(svg_file, "r", encoding="utf-8") as f:
                content = f.read()
                # Remplacement de la couleur de remplissage
                if 'fill="' in content:
                    import re
                    content = re.sub(r'fill="[^"]*"', f'fill="{color}"', content)
                elif "<path" in content:
                    content = content.replace("<path", f'<path fill="{color}"')
                svg_str = content
        except Exception:
            pass

    if not svg_str and icon_name in MATERIAL_SYMBOLS_PATHS:
        path = MATERIAL_SYMBOLS_PATHS[icon_name]
        svg_str = f'<svg xmlns="http://www.w3.org/2000/svg" height="24" viewBox="0 -960 960 960" width="24"><path fill="{color}" d="{path}"/></svg>'

    if not svg_str:
        # Fallback générique
        svg_str = f'<svg xmlns="http://www.w3.org/2000/svg" height="24" viewBox="0 -960 960 960" width="24"><circle cx="480" cy="-480" r="300" fill="{color}"/></svg>'

    data = QByteArray(svg_str.encode("utf-8"))
    _svg_cache[cache_key] = data
    return data


def get_pixmap(icon_name: str, color: str = DEFAULT_ICON_COLOR, size: int = 24) -> QPixmap:
    """Génère un QPixmap haute résolution pour l'icône demandée."""
    svg_data = get_svg_data(icon_name, color)
    renderer = QSvgRenderer(svg_data)

    pix = QPixmap(size, size)
    pix.fill(Qt.GlobalColor.transparent)

    painter = QPainter(pix)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
    renderer.render(painter)
    painter.end()

    return pix


def get_icon(icon_name: str, color: str = DEFAULT_ICON_COLOR, active_color: Optional[str] = None) -> QIcon:
    """Génère un QIcon complet (avec état normal et actif)."""
    icon = QIcon()
    for s in [16, 20, 24, 32, 48]:
        pix_normal = get_pixmap(icon_name, color=color, size=s)
        icon.addPixmap(pix_normal, QIcon.Mode.Normal, QIcon.State.Off)

        act_col = active_color or color
        pix_active = get_pixmap(icon_name, color=act_col, size=s)
        icon.addPixmap(pix_active, QIcon.Mode.Normal, QIcon.State.On)
        icon.addPixmap(pix_active, QIcon.Mode.Active, QIcon.State.Off)
        icon.addPixmap(pix_active, QIcon.Mode.Selected, QIcon.State.Off)

    return icon
